// ============================================
// ESG Domain Pack — Question Bank: supplier-form records
// ============================================
// What buyer SAQs ask that VSME does not: the policy-existence yes/no family (the bulk of every
// SAQ), management-system questions, supplier-management, due-diligence and raw-material
// questions. Phrasings come from the public Drive Sustainability SAQ 5.0, our own templates and
// our own words — never a proprietary platform's sentence. Legal basis is per record: LkSG,
// EUDR, CBAM, REACH and conflict-minerals questions rest on their own statutes; the rest is the
// buyer asking on its own account.
// A policy-existence question: "Do you have a formal X policy?" Answered from the policies list
// and the matching status field; never with a KPI from the same topic.
function policy(id, topic, en, de, variants, needs, refs, extra = {}) {
    return {
        id, topic, answerType: 'yesno', intent: { en, de }, variants, refs, needs,
        legalBasis: 'none',
        needsDocument: { en: 'the policy document', de: 'das Richtliniendokument' },
        ...extra,
    };
}
